// Lesson: Stateless MCP Server with Registry and Governance (phase 19 / lesson 13)
// Go port of code/main.py. Go standard library only.
// Source: phases/19-capstone-projects/13-mcp-server-with-registry/docs/en.md
// Run: go run code/main.go

package main

import (
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"math"
	"regexp"
	"sort"
	"strconv"
	"strings"
	"time"
	"unicode/utf8"
)

const (
	protocolVersion = "2026-07-28"
	registrySchema  = "https://static.modelcontextprotocol.io/schemas/2025-12-11/server.schema.json"
	publisherDomain = "example.com"
)

var (
	serverNameRe   = regexp.MustCompile(`^[a-zA-Z0-9.-]+/[a-zA-Z0-9._-]+$`)
	domainLabelRe  = regexp.MustCompile(`^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$`)
	remoteURLRe    = regexp.MustCompile(`^https?://\S+$`)
	versionRangeRe = regexp.MustCompile(`(?i)(?:^[~^<>=]|[*]|(?:^|\.)x(?:$|\.))`)
	emailRe        = regexp.MustCompile(`[\p{L}\p{N}_.+-]+@[\p{L}\p{N}_-]+\.[\p{L}\p{N}_.-]+`)
	ssnRe          = regexp.MustCompile(`\b\d{3}-\d{2}-\d{4}\b`)
)

type kv struct {
	k string
	v any
}

type obj []kv

func (o obj) get(key string) (any, bool) {
	for _, item := range o {
		if item.k == key {
			return item.v, true
		}
	}
	return nil, false
}

func (o obj) has(key string) bool {
	_, ok := o.get(key)
	return ok
}

func pyFloatRepr(x float64) string {
	if math.IsNaN(x) {
		return "NaN"
	}
	if math.IsInf(x, 1) {
		return "Infinity"
	}
	if math.IsInf(x, -1) {
		return "-Infinity"
	}
	if x == math.Trunc(x) && math.Abs(x) < 1e16 {
		return strconv.FormatFloat(x, 'f', 1, 64)
	}
	exp := math.Floor(math.Log10(math.Abs(x)))
	if exp < -4 || exp >= 16 {
		s := strconv.FormatFloat(x, 'e', -1, 64)
		mant, e, _ := strings.Cut(s, "e")
		sign := e[0]
		digits := strings.TrimLeft(e[1:], "0")
		if len(digits) < 2 {
			digits = strings.Repeat("0", 2-len(digits)) + digits
		}
		return mant + "e" + string(sign) + digits
	}
	return strconv.FormatFloat(x, 'f', -1, 64)
}

func jsonString(s string, ensureASCII bool) string {
	var b strings.Builder
	b.WriteByte('"')
	for _, r := range s {
		switch r {
		case '"':
			b.WriteString(`\"`)
		case '\\':
			b.WriteString(`\\`)
		case '\n':
			b.WriteString(`\n`)
		case '\r':
			b.WriteString(`\r`)
		case '\t':
			b.WriteString(`\t`)
		case '\b':
			b.WriteString(`\b`)
		case '\f':
			b.WriteString(`\f`)
		default:
			switch {
			case r < 0x20:
				fmt.Fprintf(&b, `\u%04x`, r)
			case ensureASCII && r > 0x7e && r > 0xffff:
				r1, r2 := utf16Pair(r)
				fmt.Fprintf(&b, `\u%04x\u%04x`, r1, r2)
			case ensureASCII && r > 0x7e:
				fmt.Fprintf(&b, `\u%04x`, r)
			default:
				b.WriteRune(r)
			}
		}
	}
	b.WriteByte('"')
	return b.String()
}

func utf16Pair(r rune) (rune, rune) {
	r -= 0x10000
	return 0xd800 + (r>>10)&0x3ff, 0xdc00 + r&0x3ff
}

type dumpOpts struct {
	indent      int
	sortKeys    bool
	ensureASCII bool
	compact     bool
}

func dumps(v any, o dumpOpts) string {
	return dumpValue(v, o, 0)
}

func dumpValue(v any, o dumpOpts, level int) string {
	itemSep, keySep := ", ", ": "
	if o.compact {
		itemSep, keySep = ",", ":"
	}
	switch t := v.(type) {
	case nil:
		return "null"
	case bool:
		if t {
			return "true"
		}
		return "false"
	case int:
		return strconv.Itoa(t)
	case float64:
		return pyFloatRepr(t)
	case string:
		return jsonString(t, o.ensureASCII)
	case []any:
		if len(t) == 0 {
			return "[]"
		}
		items := make([]string, len(t))
		for i, x := range t {
			items[i] = dumpValue(x, o, level+1)
		}
		return wrap("[", "]", items, o, level, itemSep)
	case obj:
		if len(t) == 0 {
			return "{}"
		}
		entries := append(obj(nil), t...)
		if o.sortKeys {
			sort.SliceStable(entries, func(i, j int) bool { return entries[i].k < entries[j].k })
		}
		items := make([]string, len(entries))
		for i, e := range entries {
			items[i] = jsonString(e.k, o.ensureASCII) + keySep + dumpValue(e.v, o, level+1)
		}
		return wrap("{", "}", items, o, level, itemSep)
	}
	panic(fmt.Sprintf("unsupported value %T", v))
}

func wrap(open, close string, items []string, o dumpOpts, level int, itemSep string) string {
	if o.indent < 0 {
		return open + strings.Join(items, itemSep) + close
	}
	pad := "\n" + strings.Repeat(" ", o.indent*(level+1))
	return open + pad + strings.Join(items, ","+pad) + "\n" + strings.Repeat(" ", o.indent*level) + close
}

func pyDumps(v any) string {
	return dumps(v, dumpOpts{indent: -1, ensureASCII: true})
}

func pyDumpsIndent(v any) string {
	return dumps(v, dumpOpts{indent: 2, ensureASCII: true})
}

func pyStrRepr(s string) string {
	quote := "'"
	if strings.Contains(s, "'") && !strings.Contains(s, `"`) {
		quote = `"`
	}
	var b strings.Builder
	b.WriteString(quote)
	for _, r := range s {
		switch {
		case r == '\\':
			b.WriteString(`\\`)
		case string(r) == quote:
			b.WriteString(`\` + quote)
		case r == '\n':
			b.WriteString(`\n`)
		case r == '\r':
			b.WriteString(`\r`)
		case r == '\t':
			b.WriteString(`\t`)
		case r < 0x20 || r == 0x7f:
			fmt.Fprintf(&b, `\x%02x`, r)
		default:
			b.WriteRune(r)
		}
	}
	b.WriteString(quote)
	return b.String()
}

func pyRepr(v any) string {
	switch t := v.(type) {
	case nil:
		return "None"
	case bool:
		if t {
			return "True"
		}
		return "False"
	case int:
		return strconv.Itoa(t)
	case float64:
		r := pyFloatRepr(t)
		switch r {
		case "NaN":
			return "nan"
		case "Infinity":
			return "inf"
		case "-Infinity":
			return "-inf"
		}
		return r
	case string:
		return pyStrRepr(t)
	case []any:
		items := make([]string, len(t))
		for i, x := range t {
			items[i] = pyRepr(x)
		}
		return "[" + strings.Join(items, ", ") + "]"
	case obj:
		items := make([]string, len(t))
		for i, e := range t {
			items[i] = pyStrRepr(e.k) + ": " + pyRepr(e.v)
		}
		return "{" + strings.Join(items, ", ") + "}"
	}
	panic(fmt.Sprintf("unsupported value %T", v))
}

func parseJSON(text string) (any, error) {
	dec := json.NewDecoder(strings.NewReader(text))
	dec.UseNumber()
	v, err := parseValue(dec)
	if err != nil {
		return nil, err
	}
	if _, err := dec.Token(); !errors.Is(err, io.EOF) {
		return nil, errors.New("trailing data")
	}
	return v, nil
}

func parseValue(dec *json.Decoder) (any, error) {
	tok, err := dec.Token()
	if err != nil {
		return nil, err
	}
	switch t := tok.(type) {
	case json.Delim:
		if t == '[' {
			out := []any{}
			for dec.More() {
				v, err := parseValue(dec)
				if err != nil {
					return nil, err
				}
				out = append(out, v)
			}
			_, err := dec.Token()
			return out, err
		}
		out := obj{}
		for dec.More() {
			keyTok, err := dec.Token()
			if err != nil {
				return nil, err
			}
			v, err := parseValue(dec)
			if err != nil {
				return nil, err
			}
			out = append(out, kv{keyTok.(string), v})
		}
		_, err := dec.Token()
		return out, err
	case json.Number:
		if i, err := strconv.Atoi(t.String()); err == nil {
			return i, nil
		}
		f, err := t.Float64()
		return f, err
	default:
		return t, nil
	}
}

func requestMeta() obj {
	return obj{
		{"io.modelcontextprotocol/protocolVersion", protocolVersion},
		{"io.modelcontextprotocol/clientCapabilities", obj{}},
		{"io.modelcontextprotocol/clientInfo", obj{{"name", "registry-capstone-client"}, {"version", "1.0.0"}}},
	}
}

func errorResult(code int, message string, data obj) obj {
	detail := obj{{"code", code}, {"message", message}}
	if data != nil {
		detail = append(detail, kv{"data", data})
	}
	return obj{{"error", detail}}
}

func validateMeta(meta any) obj {
	m, ok := meta.(obj)
	if !ok {
		return errorResult(-32602, "params._meta must be an object", nil)
	}
	requested, ok := m.get("io.modelcontextprotocol/protocolVersion")
	reqStr, isStr := requested.(string)
	if !ok || !isStr {
		return errorResult(-32602, "protocolVersion must be a string", nil)
	}
	if reqStr != protocolVersion {
		return errorResult(-32022, "Unsupported protocol version", obj{{"supported", []any{protocolVersion}}, {"requested", reqStr}})
	}
	caps, _ := m.get("io.modelcontextprotocol/clientCapabilities")
	if _, ok := caps.(obj); !ok {
		return errorResult(-32602, "clientCapabilities must be an object", nil)
	}
	return nil
}

type ToolSchema struct {
	Name          string
	RequiredScope string
	Destructive   bool
	Description   string
	InputSchema   obj
}

type Handler func(args obj) (obj, error)

type MCPServer struct {
	Name          string
	Title         string
	Description   string
	Version       string
	URL           string
	TrustedIssuer string
	Tools         map[string]ToolSchema
	Handlers      map[string]Handler
}

func newServer(name, title, description, version, url, issuer string) *MCPServer {
	return &MCPServer{
		Name: name, Title: title, Description: description, Version: version, URL: url, TrustedIssuer: issuer,
		Tools: map[string]ToolSchema{}, Handlers: map[string]Handler{},
	}
}

func (s *MCPServer) serverInfo() obj {
	return obj{{"name", s.Name}, {"version", s.Version}}
}

func (s *MCPServer) Register(schema ToolSchema, handler Handler) error {
	if _, ok := s.Tools[schema.Name]; ok {
		return fmt.Errorf("duplicate tool: %s", schema.Name)
	}
	s.Tools[schema.Name] = schema
	s.Handlers[schema.Name] = handler
	return nil
}

func (s *MCPServer) result(fields ...kv) obj {
	out := obj{{"resultType", "complete"}}
	out = append(out, fields...)
	return append(out, kv{"_meta", obj{{"io.modelcontextprotocol/serverInfo", s.serverInfo()}}})
}

func (s *MCPServer) Discover(meta obj) obj {
	if invalid := validateMeta(meta); invalid != nil {
		return invalid
	}
	return s.result(
		kv{"supportedVersions", []any{protocolVersion}},
		kv{"capabilities", obj{{"tools", obj{{"listChanged", false}}}}},
		kv{"ttlMs", 3_600_000},
		kv{"cacheScope", "public"},
	)
}

func (s *MCPServer) ToolsList(meta obj) obj {
	if invalid := validateMeta(meta); invalid != nil {
		return invalid
	}
	names := make([]string, 0, len(s.Tools))
	for name := range s.Tools {
		names = append(names, name)
	}
	sort.Strings(names)
	tools := []any{}
	for _, name := range names {
		tool := s.Tools[name]
		tools = append(tools, obj{
			{"name", tool.Name},
			{"description", tool.Description},
			{"inputSchema", tool.InputSchema},
			{"annotations", obj{{"readOnlyHint", !tool.Destructive}, {"destructiveHint", tool.Destructive}}},
		})
	}
	return s.result(kv{"tools", tools}, kv{"ttlMs", 60_000}, kv{"cacheScope", "private"})
}

func (s *MCPServer) RegistryDocument() obj {
	return obj{
		{"$schema", registrySchema},
		{"name", s.Name},
		{"title", s.Title},
		{"description", s.Description},
		{"version", s.Version},
		{"remotes", []any{obj{{"type", "streamable-http"}, {"url", s.URL}}}},
	}
}

type Token struct {
	User      string
	Issuer    string
	Audience  string
	Scopes    map[string]bool
	ExpiresAt float64
}

func (t Token) HasScope(scope string) bool {
	return t.Scopes[scope]
}

func (t Token) IsExpired(now float64) bool {
	return now >= t.ExpiresAt
}

func argumentsDigest(args obj) string {
	normalized := dumps(args, dumpOpts{indent: -1, sortKeys: true, compact: true})
	sum := sha256.Sum256([]byte(normalized))
	return hex.EncodeToString(sum[:])
}

type ApprovalRecord struct {
	Actor           string
	Tool            string
	ArgumentsDigest string
	Target          string
	ExpiresAt       float64
}

func approvalForAction(actor, tool string, args obj, target string, expiresAt float64) ApprovalRecord {
	return ApprovalRecord{actor, tool, argumentsDigest(args), target, expiresAt}
}

func (a ApprovalRecord) Authorize(actor, tool string, args obj, target string, now float64) (bool, string) {
	if a.Actor != actor {
		return false, "approval actor does not match token subject"
	}
	if a.Tool != tool {
		return false, "approval tool does not match requested tool"
	}
	if a.Target != target {
		return false, "approval target does not match this server"
	}
	if a.ArgumentsDigest != argumentsDigest(args) {
		return false, "approval arguments do not match requested action"
	}
	if now >= a.ExpiresAt {
		return false, "approval has expired"
	}
	return true, "ok"
}

func policyDecide(server *MCPServer, tool string, token Token, args obj, now float64, approval *ApprovalRecord) (bool, string) {
	if token.Issuer != server.TrustedIssuer {
		return false, "token issuer is not trusted by this server"
	}
	if token.Audience != server.URL {
		return false, "token audience does not match this server"
	}
	if token.IsExpired(now) {
		return false, "token has expired"
	}
	schema, ok := server.Tools[tool]
	if !ok {
		return false, "no such tool: " + tool
	}
	if !token.HasScope(schema.RequiredScope) {
		return false, "missing scope: " + schema.RequiredScope
	}
	if utf8.RuneCountInString(pyDumps(args)) > 8192 {
		return false, "payload too large"
	}
	if schema.Destructive {
		if approval == nil {
			return false, "destructive tool requires an action-bound approval"
		}
		if approved, reason := approval.Authorize(token.User, tool, args, server.URL, now); !approved {
			return false, reason
		}
	}
	return true, "ok"
}

func redact(payload obj) obj {
	text := pyDumps(payload)
	text = emailRe.ReplaceAllString(text, "[email]")
	text = ssnRe.ReplaceAllString(text, "[ssn]")
	v, err := parseJSON(text)
	if err != nil {
		panic(err)
	}
	return v.(obj)
}

type AuditEntry struct {
	Ts               float64
	User             string
	Issuer           string
	Tool             string
	Outcome          string
	ArgsRedacted     obj
	ResponseRedacted obj
}

func (e AuditEntry) asDict() obj {
	return obj{
		{"ts", e.Ts},
		{"user", e.User},
		{"issuer", e.Issuer},
		{"tool", e.Tool},
		{"outcome", e.Outcome},
		{"args_redacted", e.ArgsRedacted},
		{"response_redacted", e.ResponseRedacted},
	}
}

func nowSeconds() float64 {
	return float64(time.Now().UnixNano()) / 1e9
}

func dispatch(server *MCPServer, token Token, tool string, args obj, meta obj, audit *[]AuditEntry, approval *ApprovalRecord) obj {
	if invalid := validateMeta(meta); invalid != nil {
		return invalid
	}
	now := nowSeconds()
	allowed, reason := policyDecide(server, tool, token, args, now, approval)
	if !allowed {
		*audit = append(*audit, AuditEntry{now, token.User, token.Issuer, tool, "denied:" + reason, redact(args), obj{}})
		return errorResult(-32000, reason, nil)
	}
	response, err := server.Handlers[tool](args)
	if err != nil {
		*audit = append(*audit, AuditEntry{now, token.User, token.Issuer, tool, "handler_error", redact(args), obj{}})
		return server.result(kv{"content", []any{obj{{"type", "text"}, {"text", err.Error()}}}}, kv{"isError", true})
	}
	*audit = append(*audit, AuditEntry{now, token.User, token.Issuer, tool, "allowed", redact(args), redact(response)})
	return server.result(
		kv{"content", []any{obj{{"type", "text"}, {"text", pyDumps(response)}}}},
		kv{"structuredContent", response},
		kv{"isError", false},
	)
}

func strLenBetween(v any, lo, hi int) bool {
	s, ok := v.(string)
	if !ok {
		return false
	}
	n := utf8.RuneCountInString(s)
	return n >= lo && n <= hi
}

func validateRegistryDocument(document any) []string {
	doc, ok := document.(obj)
	if !ok {
		return []string{"server.json must be an object"}
	}
	issues := []string{}
	for _, key := range []string{"name", "description", "version"} {
		if !doc.has(key) {
			issues = append(issues, "missing "+key)
		}
	}
	if schemaURI, ok := doc.get("$schema"); ok && schemaURI != registrySchema {
		issues = append(issues, "unsupported registry schema")
	}
	if name, ok := doc.get("name"); ok {
		s, _ := name.(string)
		if !strLenBetween(name, 3, 200) || !serverNameRe.MatchString(s) {
			issues = append(issues, "name must match namespace/server and be 3-200 characters")
		}
	}
	if description, ok := doc.get("description"); ok && !strLenBetween(description, 1, 100) {
		issues = append(issues, "description must be a 1-100 character string")
	}
	if title, ok := doc.get("title"); ok && !strLenBetween(title, 1, 100) {
		issues = append(issues, "title must be a 1-100 character string")
	}
	if version, ok := doc.get("version"); ok {
		s, _ := version.(string)
		if !strLenBetween(version, 1, 255) || versionRangeRe.MatchString(s) || strings.EqualFold(s, "latest") {
			issues = append(issues, "version must be one concrete 1-255 character version")
		}
	}
	remotesVal, _ := doc.get("remotes")
	remotes, ok := remotesVal.([]any)
	if !ok || len(remotes) == 0 {
		issues = append(issues, "remote profile requires a non-empty remotes list")
		return issues
	}
	for index, remoteVal := range remotes {
		remote, ok := remoteVal.(obj)
		if !ok {
			issues = append(issues, fmt.Sprintf("remotes[%d] must be an object", index))
			continue
		}
		if typ, _ := remote.get("type"); typ != "streamable-http" && typ != "sse" {
			issues = append(issues, fmt.Sprintf("remotes[%d].type must be streamable-http or sse", index))
		}
		remoteURL, _ := remote.get("url")
		if s, ok := remoteURL.(string); !ok || !remoteURLRe.MatchString(s) {
			issues = append(issues, fmt.Sprintf("remotes[%d].url must be an http(s) URL template", index))
		}
	}
	return issues
}

func reverseDNSNamespace(domain string) (string, error) {
	normalized := strings.TrimRight(strings.ToLower(domain), ".")
	labels := strings.Split(normalized, ".")
	if len(labels) < 2 {
		return "", errors.New("publisher domain must be a valid multi-label DNS name")
	}
	for _, label := range labels {
		if !domainLabelRe.MatchString(label) {
			return "", errors.New("publisher domain must be a valid multi-label DNS name")
		}
	}
	for i, j := 0, len(labels)-1; i < j; i, j = i+1, j-1 {
		labels[i], labels[j] = labels[j], labels[i]
	}
	return strings.Join(labels, "."), nil
}

func validatePublisherNamespace(document any, verifiedDomain string) ([]string, error) {
	doc, ok := document.(obj)
	if !ok {
		return nil, nil
	}
	nameVal, _ := doc.get("name")
	name, ok := nameVal.(string)
	if !ok {
		return nil, nil
	}
	namespace, _, _ := strings.Cut(name, "/")
	expected, err := reverseDNSNamespace(verifiedDomain)
	if err != nil {
		return nil, err
	}
	if namespace != expected && !strings.HasPrefix(namespace, expected+".") {
		return []string{fmt.Sprintf("name namespace must be %s or its child for verified domain %s", expected, verifiedDomain)}, nil
	}
	return nil, nil
}

func validateRuntimeAlignment(document obj, discovery any) []string {
	disc, ok := discovery.(obj)
	if !ok {
		return []string{"server/discover result must be an object"}
	}
	metaVal, _ := disc.get("_meta")
	var serverInfo obj
	if meta, ok := metaVal.(obj); ok {
		si, _ := meta.get("io.modelcontextprotocol/serverInfo")
		serverInfo, _ = si.(obj)
	}
	if serverInfo == nil {
		return []string{"server/discover must include serverInfo for registry drift checks"}
	}
	issues := []string{}
	siName, _ := serverInfo.get("name")
	docName, _ := document.get("name")
	if siName != docName {
		issues = append(issues, "runtime serverInfo.name does not match server.json name")
	}
	siVersion, _ := serverInfo.get("version")
	docVersion, _ := document.get("version")
	if siVersion != docVersion {
		issues = append(issues, "runtime serverInfo.version does not match server.json version")
	}
	return issues
}

type Registry struct {
	PublisherDomain  string
	Entries          map[string]obj
	RuntimeDiscovery map[string]obj
}

func newRegistry() *Registry {
	return &Registry{PublisherDomain: publisherDomain, Entries: map[string]obj{}, RuntimeDiscovery: map[string]obj{}}
}

func (r *Registry) Register(server *MCPServer) error {
	document := server.RegistryDocument()
	issues := validateRegistryDocument(document)
	nsIssues, err := validatePublisherNamespace(document, r.PublisherDomain)
	if err != nil {
		return err
	}
	issues = append(issues, nsIssues...)
	if len(issues) > 0 {
		return errors.New(strings.Join(issues, "; "))
	}
	discovery := server.Discover(requestMeta())
	if discovery.has("error") {
		return errors.New("runtime discovery failed")
	}
	if alignment := validateRuntimeAlignment(document, discovery); len(alignment) > 0 {
		return errors.New(strings.Join(alignment, "; "))
	}
	r.Entries[server.Name] = document
	r.RuntimeDiscovery[server.Name] = discovery
	return nil
}

func (r *Registry) Search(query string) []string {
	needle := strings.ToLower(query)
	out := []string{}
	for name, entry := range r.Entries {
		title, _ := entry.get("title")
		description, _ := entry.get("description")
		if strings.Contains(strings.ToLower(name), needle) ||
			strings.Contains(strings.ToLower(title.(string)), needle) ||
			strings.Contains(strings.ToLower(description.(string)), needle) {
			out = append(out, name)
		}
	}
	sort.Strings(out)
	return out
}

func stringArg(args obj, key string) (string, error) {
	v, ok := args.get(key)
	if !ok {
		return "", fmt.Errorf("'%s'", key)
	}
	s, _ := v.(string)
	return s, nil
}

func objectSchema(prop string) obj {
	return obj{
		{"type", "object"},
		{"properties", obj{{prop, obj{{"type", "string"}}}}},
		{"required", []any{prop}},
		{"additionalProperties", false},
	}
}

func mustRegister(server *MCPServer, schema ToolSchema, handler Handler) {
	if err := server.Register(schema, handler); err != nil {
		panic(err)
	}
}

func buildReadonlyServer() *MCPServer {
	server := newServer(
		"com.example/internal-readonly",
		"Internal Read-Only Tools",
		"Read-only incident and data lookup tools.",
		"1.0.0",
		"https://mcp.internal.example.com/readonly",
		"https://auth.internal.example.com",
	)
	mustRegister(server,
		ToolSchema{"postgres.readonly", "postgres:query:readonly", false, "Run an approved read-only query.", objectSchema("sql")},
		func(args obj) (obj, error) {
			sql, err := stringArg(args, "sql")
			if err != nil {
				return nil, err
			}
			return obj{{"rows", []any{[]any{1}}}, {"sql", sql}}, nil
		},
	)
	mustRegister(server,
		ToolSchema{"s3.list", "s3:list", false, "List objects in one approved bucket.", objectSchema("bucket")},
		func(args obj) (obj, error) {
			bucket, err := stringArg(args, "bucket")
			if err != nil {
				return nil, err
			}
			return obj{{"bucket", bucket}, {"objects", []any{"a/b.txt"}}}, nil
		},
	)
	return server
}

func buildDestructiveServer() *MCPServer {
	server := newServer(
		"com.example/internal-destructive",
		"Internal Destructive Tools",
		"State-changing tools behind explicit approval.",
		"1.0.0",
		"https://mcp.internal.example.com/destructive",
		"https://auth.internal.example.com",
	)
	mustRegister(server,
		ToolSchema{"jira.create", "jira:write", true, "Create one Jira issue after explicit approval.", objectSchema("title")},
		func(args obj) (obj, error) {
			title, err := stringArg(args, "title")
			if err != nil {
				return nil, err
			}
			return obj{{"id", "PROJ-99"}, {"title", title}, {"created", true}}, nil
		},
	)
	return server
}

func main() {
	readonly := buildReadonlyServer()
	destructive := buildDestructiveServer()
	registry := newRegistry()
	for _, server := range []*MCPServer{readonly, destructive} {
		if err := registry.Register(server); err != nil {
			panic(err)
		}
	}
	audit := []AuditEntry{}

	readonlyToken := Token{"u42", readonly.TrustedIssuer, readonly.URL, map[string]bool{"postgres:query:readonly": true, "s3:list": true}, nowSeconds() + 3_600}
	approvedToken := Token{"u42", destructive.TrustedIssuer, destructive.URL, map[string]bool{"jira:write": true}, nowSeconds() + 3_600}
	approvedArgs := obj{{"title", "new bug"}}
	approval := approvalForAction(approvedToken.User, "jira.create", approvedArgs, destructive.URL, nowSeconds()+900)

	fmt.Println("=== registry metadata and runtime discovery ===")
	fmt.Println(pyDumpsIndent(registry.Entries[readonly.Name]))
	fmt.Println(pyDumpsIndent(registry.RuntimeDiscovery[readonly.Name]))
	fmt.Println("tools:", pyDumpsIndent(readonly.ToolsList(requestMeta())))

	fmt.Println("\n=== policy-gated calls ===")
	fmt.Println(pyRepr(dispatch(readonly, readonlyToken, "postgres.readonly", obj{{"sql", "SELECT 1"}}, requestMeta(), &audit, nil)))
	fmt.Println(pyRepr(dispatch(destructive, approvedToken, "jira.create", approvedArgs, requestMeta(), &audit, &approval)))

	fmt.Println("\n=== audit log ===")
	for _, entry := range audit {
		fmt.Println(dumps(entry.asDict(), dumpOpts{indent: -1, sortKeys: true, ensureASCII: true}))
	}
}

"""Stateless MCP server, registry metadata, policy, and audit simulation.

This stdlib-only model keeps two discovery layers separate:

* ``server.json`` describes installation and remote transport metadata to a
  registry.
* ``server/discover`` reports live protocol versions and capabilities.

It does not open a network listener, validate a real OAuth token, call OPA, or
publish to a registry. Run with ``python3 code/main.py`` from the lesson root.
"""

from __future__ import annotations

import hashlib
import json
import re
import time
from copy import deepcopy
from dataclasses import asdict, dataclass, field
from typing import Callable


PROTOCOL_VERSION = "2026-07-28"
REGISTRY_SCHEMA = "https://static.modelcontextprotocol.io/schemas/2025-12-11/server.schema.json"
PUBLISHER_DOMAIN = "example.com"
SERVER_NAME_RE = re.compile(r"^[a-zA-Z0-9.-]+/[a-zA-Z0-9._-]+$")
DOMAIN_LABEL_RE = re.compile(r"^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$")
REMOTE_URL_RE = re.compile(r"^https?://\S+$")
VERSION_RANGE_RE = re.compile(r"(?:^[~^<>=]|[*]|(?:^|\.)x(?:$|\.))", re.IGNORECASE)


def request_meta() -> dict:
    return {
        "io.modelcontextprotocol/protocolVersion": PROTOCOL_VERSION,
        "io.modelcontextprotocol/clientCapabilities": {},
        "io.modelcontextprotocol/clientInfo": {
            "name": "registry-capstone-client",
            "version": "1.0.0",
        },
    }


def error(code: int, message: str, data: dict | None = None) -> dict:
    detail = {"code": code, "message": message}
    if data is not None:
        detail["data"] = data
    return {"error": detail}


def validate_meta(meta: object) -> dict | None:
    if not isinstance(meta, dict):
        return error(-32602, "params._meta must be an object")
    requested = meta.get("io.modelcontextprotocol/protocolVersion")
    if not isinstance(requested, str):
        return error(-32602, "protocolVersion must be a string")
    if requested != PROTOCOL_VERSION:
        return error(
            -32022,
            "Unsupported protocol version",
            {"supported": [PROTOCOL_VERSION], "requested": requested},
        )
    if not isinstance(meta.get("io.modelcontextprotocol/clientCapabilities"), dict):
        return error(-32602, "clientCapabilities must be an object")
    return None


@dataclass(frozen=True)
class ToolSchema:
    name: str
    required_scope: str
    destructive: bool
    description: str
    input_schema: dict


Handler = Callable[[dict], dict]


@dataclass
class MCPServer:
    name: str
    title: str
    description: str
    version: str
    url: str
    trusted_issuer: str
    tools: dict[str, ToolSchema] = field(default_factory=dict)
    handlers: dict[str, Handler] = field(default_factory=dict)

    @property
    def server_info(self) -> dict:
        return {"name": self.name, "version": self.version}

    def register(self, schema: ToolSchema, handler: Handler) -> None:
        if schema.name in self.tools:
            raise ValueError(f"duplicate tool: {schema.name}")
        self.tools[schema.name] = schema
        self.handlers[schema.name] = handler

    def result(self, **fields: object) -> dict:
        return {
            "resultType": "complete",
            **fields,
            "_meta": {"io.modelcontextprotocol/serverInfo": self.server_info},
        }

    def discover(self, meta: dict) -> dict:
        invalid = validate_meta(meta)
        if invalid:
            return invalid
        return self.result(
            supportedVersions=[PROTOCOL_VERSION],
            capabilities={"tools": {"listChanged": False}},
            ttlMs=3_600_000,
            cacheScope="public",
        )

    def tools_list(self, meta: dict) -> dict:
        invalid = validate_meta(meta)
        if invalid:
            return invalid
        tools = [
            {
                "name": tool.name,
                "description": tool.description,
                "inputSchema": tool.input_schema,
                "annotations": {
                    "readOnlyHint": not tool.destructive,
                    "destructiveHint": tool.destructive,
                },
            }
            for tool in sorted(self.tools.values(), key=lambda item: item.name)
        ]
        return self.result(tools=tools, ttlMs=60_000, cacheScope="private")

    def registry_document(self) -> dict:
        return {
            "$schema": REGISTRY_SCHEMA,
            "name": self.name,
            "title": self.title,
            "description": self.description,
            "version": self.version,
            "remotes": [{"type": "streamable-http", "url": self.url}],
        }


@dataclass(frozen=True)
class Token:
    user: str
    issuer: str
    audience: str
    scopes: frozenset[str]
    expires_at: float

    def has_scope(self, scope: str) -> bool:
        return scope in self.scopes

    def is_expired(self, now: float) -> bool:
        return now >= self.expires_at


def arguments_digest(args: dict) -> str:
    normalized = json.dumps(
        args,
        ensure_ascii=False,
        separators=(",", ":"),
        sort_keys=True,
    )
    return hashlib.sha256(normalized.encode("utf-8")).hexdigest()


@dataclass(frozen=True)
class ApprovalRecord:
    actor: str
    tool: str
    arguments_digest: str
    target: str
    expires_at: float

    @classmethod
    def for_action(
        cls,
        actor: str,
        tool: str,
        args: dict,
        target: str,
        expires_at: float,
    ) -> ApprovalRecord:
        return cls(actor, tool, arguments_digest(args), target, expires_at)

    def authorize(
        self,
        actor: str,
        tool: str,
        args: dict,
        target: str,
        now: float,
    ) -> tuple[bool, str]:
        if self.actor != actor:
            return False, "approval actor does not match token subject"
        if self.tool != tool:
            return False, "approval tool does not match requested tool"
        if self.target != target:
            return False, "approval target does not match this server"
        if self.arguments_digest != arguments_digest(args):
            return False, "approval arguments do not match requested action"
        if now >= self.expires_at:
            return False, "approval has expired"
        return True, "ok"


def policy_decide(
    server: MCPServer,
    tool: str,
    token: Token,
    args: dict,
    now: float,
    approval: ApprovalRecord | None = None,
) -> tuple[bool, str]:
    if token.issuer != server.trusted_issuer:
        return False, "token issuer is not trusted by this server"
    if token.audience != server.url:
        return False, "token audience does not match this server"
    if token.is_expired(now):
        return False, "token has expired"
    schema = server.tools.get(tool)
    if schema is None:
        return False, f"no such tool: {tool}"
    if not token.has_scope(schema.required_scope):
        return False, f"missing scope: {schema.required_scope}"
    if len(json.dumps(args)) > 8192:
        return False, "payload too large"
    if schema.destructive:
        if approval is None:
            return False, "destructive tool requires an action-bound approval"
        approved, reason = approval.authorize(
            token.user,
            tool,
            args,
            server.url,
            now,
        )
        if not approved:
            return False, reason
    return True, "ok"


def redact(payload: dict) -> dict:
    text = json.dumps(payload)
    text = re.sub(r"[\w.+-]+@[\w-]+\.[\w.-]+", "[email]", text)
    text = re.sub(r"\b\d{3}-\d{2}-\d{4}\b", "[ssn]", text)
    return json.loads(text)


@dataclass(frozen=True)
class AuditEntry:
    ts: float
    user: str
    issuer: str
    tool: str
    outcome: str
    args_redacted: dict
    response_redacted: dict


def dispatch(
    server: MCPServer,
    token: Token,
    tool: str,
    args: dict,
    meta: dict,
    audit: list[AuditEntry],
    approval: ApprovalRecord | None = None,
) -> dict:
    invalid = validate_meta(meta)
    if invalid:
        return invalid
    now = time.time()
    allowed, reason = policy_decide(server, tool, token, args, now, approval)
    if not allowed:
        audit.append(
            AuditEntry(now, token.user, token.issuer, tool, f"denied:{reason}", redact(args), {})
        )
        return error(-32000, reason)
    try:
        response = server.handlers[tool](args)
    except Exception as exc:
        audit.append(
            AuditEntry(now, token.user, token.issuer, tool, "handler_error", redact(args), {})
        )
        return server.result(
            content=[{"type": "text", "text": str(exc)}],
            isError=True,
        )
    audit.append(
        AuditEntry(
            now,
            token.user,
            token.issuer,
            tool,
            "allowed",
            redact(args),
            redact(response),
        )
    )
    return server.result(
        content=[{"type": "text", "text": json.dumps(response)}],
        structuredContent=response,
        isError=False,
    )


def validate_registry_document(document: object) -> list[str]:
    """Validate the official fields used by this lesson's remote-only profile.

    This dependency-free subset is not a replacement for validation against
    the complete pinned Registry JSON Schema before publication.
    """
    if not isinstance(document, dict):
        return ["server.json must be an object"]
    issues: list[str] = []

    for key in ("name", "description", "version"):
        if key not in document:
            issues.append(f"missing {key}")

    schema_uri = document.get("$schema")
    if "$schema" in document and schema_uri != REGISTRY_SCHEMA:
        issues.append("unsupported registry schema")

    name = document.get("name")
    if "name" in document and (
        not isinstance(name, str)
        or not 3 <= len(name) <= 200
        or SERVER_NAME_RE.fullmatch(name) is None
    ):
        issues.append("name must match namespace/server and be 3-200 characters")

    description = document.get("description")
    if "description" in document and (
        not isinstance(description, str) or not 1 <= len(description) <= 100
    ):
        issues.append("description must be a 1-100 character string")

    title = document.get("title")
    if "title" in document and (
        not isinstance(title, str) or not 1 <= len(title) <= 100
    ):
        issues.append("title must be a 1-100 character string")

    version = document.get("version")
    if "version" in document and (
        not isinstance(version, str)
        or not 1 <= len(version) <= 255
        or VERSION_RANGE_RE.search(version) is not None
        or version.casefold() == "latest"
    ):
        issues.append("version must be one concrete 1-255 character version")

    remotes = document.get("remotes")
    if not isinstance(remotes, list) or not remotes:
        issues.append("remote profile requires a non-empty remotes list")
    else:
        for index, remote in enumerate(remotes):
            if not isinstance(remote, dict):
                issues.append(f"remotes[{index}] must be an object")
                continue
            if remote.get("type") not in {"streamable-http", "sse"}:
                issues.append(f"remotes[{index}].type must be streamable-http or sse")
            remote_url = remote.get("url")
            if not isinstance(remote_url, str) or REMOTE_URL_RE.fullmatch(remote_url) is None:
                issues.append(f"remotes[{index}].url must be an http(s) URL template")
    return issues


def reverse_dns_namespace(domain: str) -> str:
    normalized = domain.casefold().rstrip(".")
    labels = normalized.split(".")
    if len(labels) < 2 or any(DOMAIN_LABEL_RE.fullmatch(label) is None for label in labels):
        raise ValueError("publisher domain must be a valid multi-label DNS name")
    return ".".join(reversed(labels))


def validate_publisher_namespace(document: object, verified_domain: str) -> list[str]:
    """Check domain ownership outside the server.json shape contract."""
    if not isinstance(document, dict) or not isinstance(document.get("name"), str):
        return []
    namespace = document["name"].partition("/")[0]
    expected = reverse_dns_namespace(verified_domain)
    if namespace != expected and not namespace.startswith(f"{expected}."):
        return [
            f"name namespace must be {expected} or its child for verified domain {verified_domain}"
        ]
    return []


def validate_runtime_alignment(document: dict, discovery: object) -> list[str]:
    """Compare publication identity with the live server/discover identity."""
    if not isinstance(discovery, dict):
        return ["server/discover result must be an object"]
    meta = discovery.get("_meta")
    server_info = (
        meta.get("io.modelcontextprotocol/serverInfo") if isinstance(meta, dict) else None
    )
    if not isinstance(server_info, dict):
        return ["server/discover must include serverInfo for registry drift checks"]

    issues: list[str] = []
    if server_info.get("name") != document.get("name"):
        issues.append("runtime serverInfo.name does not match server.json name")
    if server_info.get("version") != document.get("version"):
        issues.append("runtime serverInfo.version does not match server.json version")
    return issues


@dataclass
class Registry:
    publisher_domain: str = PUBLISHER_DOMAIN
    entries: dict[str, dict] = field(default_factory=dict)
    runtime_discovery: dict[str, dict] = field(default_factory=dict)

    def register(self, server: MCPServer) -> None:
        document = server.registry_document()
        issues = validate_registry_document(document)
        issues.extend(validate_publisher_namespace(document, self.publisher_domain))
        if issues:
            raise ValueError("; ".join(issues))
        discovery = server.discover(request_meta())
        if "error" in discovery:
            raise ValueError("runtime discovery failed")
        alignment_issues = validate_runtime_alignment(document, discovery)
        if alignment_issues:
            raise ValueError("; ".join(alignment_issues))
        self.entries[server.name] = deepcopy(document)
        self.runtime_discovery[server.name] = deepcopy(discovery)

    def search(self, query: str) -> list[str]:
        needle = query.casefold()
        return sorted(
            name
            for name, entry in self.entries.items()
            if needle in name.casefold()
            or needle in entry["title"].casefold()
            or needle in entry["description"].casefold()
        )


def build_readonly_server() -> MCPServer:
    server = MCPServer(
        name="com.example/internal-readonly",
        title="Internal Read-Only Tools",
        description="Read-only incident and data lookup tools.",
        version="1.0.0",
        url="https://mcp.internal.example.com/readonly",
        trusted_issuer="https://auth.internal.example.com",
    )
    server.register(
        ToolSchema(
            "postgres.readonly",
            "postgres:query:readonly",
            False,
            "Run an approved read-only query.",
            {
                "type": "object",
                "properties": {"sql": {"type": "string"}},
                "required": ["sql"],
                "additionalProperties": False,
            },
        ),
        lambda args: {"rows": [[1]], "sql": args["sql"]},
    )
    server.register(
        ToolSchema(
            "s3.list",
            "s3:list",
            False,
            "List objects in one approved bucket.",
            {
                "type": "object",
                "properties": {"bucket": {"type": "string"}},
                "required": ["bucket"],
                "additionalProperties": False,
            },
        ),
        lambda args: {"bucket": args["bucket"], "objects": ["a/b.txt"]},
    )
    return server


def build_destructive_server() -> MCPServer:
    server = MCPServer(
        name="com.example/internal-destructive",
        title="Internal Destructive Tools",
        description="State-changing tools behind explicit approval.",
        version="1.0.0",
        url="https://mcp.internal.example.com/destructive",
        trusted_issuer="https://auth.internal.example.com",
    )
    server.register(
        ToolSchema(
            "jira.create",
            "jira:write",
            True,
            "Create one Jira issue after explicit approval.",
            {
                "type": "object",
                "properties": {"title": {"type": "string"}},
                "required": ["title"],
                "additionalProperties": False,
            },
        ),
        lambda args: {"id": "PROJ-99", "title": args["title"], "created": True},
    )
    return server


def main() -> None:
    readonly = build_readonly_server()
    destructive = build_destructive_server()
    registry = Registry()
    registry.register(readonly)
    registry.register(destructive)
    audit: list[AuditEntry] = []

    readonly_token = Token(
        "u42",
        readonly.trusted_issuer,
        readonly.url,
        frozenset({"postgres:query:readonly", "s3:list"}),
        time.time() + 3_600,
    )
    approved_token = Token(
        "u42",
        destructive.trusted_issuer,
        destructive.url,
        frozenset({"jira:write"}),
        time.time() + 3_600,
    )
    approved_args = {"title": "new bug"}
    approval = ApprovalRecord.for_action(
        approved_token.user,
        "jira.create",
        approved_args,
        destructive.url,
        time.time() + 900,
    )

    print("=== registry metadata and runtime discovery ===")
    print(json.dumps(registry.entries[readonly.name], indent=2))
    print(json.dumps(registry.runtime_discovery[readonly.name], indent=2))
    print("tools:", json.dumps(readonly.tools_list(request_meta()), indent=2))

    print("\n=== policy-gated calls ===")
    print(
        dispatch(
            readonly,
            readonly_token,
            "postgres.readonly",
            {"sql": "SELECT 1"},
            request_meta(),
            audit,
        )
    )
    print(
        dispatch(
            destructive,
            approved_token,
            "jira.create",
            approved_args,
            request_meta(),
            audit,
            approval,
        )
    )

    print("\n=== audit log ===")
    for entry in audit:
        print(json.dumps(asdict(entry), sort_keys=True))


if __name__ == "__main__":
    main()

// Lesson: Capstone 13: Stateless MCP Server with Registry and Governance (phase 19 / lesson 13)
// TypeScript port of code/main.py. Node standard library only.
// Source: phases/19-capstone-projects/13-mcp-server-with-registry/docs/en.md
// Run: npx tsx phases/19-capstone-projects/13-mcp-server-with-registry/code/main.ts

import { createHash } from "node:crypto";

type Json = null | boolean | number | string | Json[] | { [key: string]: Json };
type Obj = { [key: string]: Json };

const PROTOCOL_VERSION = "2026-07-28";
const REGISTRY_SCHEMA = "https://static.modelcontextprotocol.io/schemas/2025-12-11/server.schema.json";
const PUBLISHER_DOMAIN = "example.com";
const SERVER_NAME_RE = /^[a-zA-Z0-9.-]+\/[a-zA-Z0-9._-]+$/;
const DOMAIN_LABEL_RE = /^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/;
const REMOTE_URL_RE = /^https?:\/\/\S+$/;
const VERSION_RANGE_RE = /(?:^[~^<>=]|[*]|(?:^|\.)x(?:$|\.))/i;

function pyStr(s: string): string {
  const quote = s.includes("'") && !s.includes('"') ? '"' : "'";
  let out = quote;
  for (const ch of s) {
    if (ch === "\\") out += "\\\\";
    else if (ch === quote) out += "\\" + ch;
    else if (ch === "\n") out += "\\n";
    else if (ch === "\t") out += "\\t";
    else if (ch === "\r") out += "\\r";
    else out += ch;
  }
  return out + quote;
}

function pyRepr(v: Json): string {
  if (v === null) return "None";
  if (typeof v === "boolean") return v ? "True" : "False";
  if (typeof v === "number") return String(v);
  if (typeof v === "string") return pyStr(v);
  if (Array.isArray(v)) return "[" + v.map(pyRepr).join(", ") + "]";
  return "{" + Object.entries(v).map(([k, x]) => `${pyStr(k)}: ${pyRepr(x)}`).join(", ") + "}";
}

function sortKeysDeep(v: Json): Json {
  if (Array.isArray(v)) return v.map(sortKeysDeep);
  if (isObj(v)) {
    const out: Obj = {};
    for (const k of Object.keys(v).sort()) out[k] = sortKeysDeep(v[k]);
    return out;
  }
  return v;
}

function jsonDumps(v: Json, sortKeys = false): string {
  if (sortKeys) return jsonDumps(sortKeysDeep(v));
  if (v === null || typeof v !== "object") {
    return JSON.stringify(v).replace(/[\u007f-￿]/g, (c) => "\\u" + c.charCodeAt(0).toString(16).padStart(4, "0"));
  }
  if (Array.isArray(v)) return "[" + v.map((x) => jsonDumps(x)).join(", ") + "]";
  return "{" + Object.entries(v).map(([k, x]) => `${jsonDumps(k)}: ${jsonDumps(x)}`).join(", ") + "}";
}

function isObj(v: unknown): v is Obj {
  return typeof v === "object" && v !== null && !Array.isArray(v);
}

function pyLen(s: string): number {
  return [...s].length;
}

function now(): number {
  return Date.now() / 1000;
}

function requestMeta(): Obj {
  return {
    "io.modelcontextprotocol/protocolVersion": PROTOCOL_VERSION,
    "io.modelcontextprotocol/clientCapabilities": {},
    "io.modelcontextprotocol/clientInfo": {
      name: "registry-capstone-client",
      version: "1.0.0",
    },
  };
}

function error(code: number, message: string, data: Obj | null = null): Obj {
  const detail: Obj = { code, message };
  if (data !== null) detail.data = data;
  return { error: detail };
}

function validateMeta(meta: unknown): Obj | null {
  if (!isObj(meta)) return error(-32602, "params._meta must be an object");
  const requested = meta["io.modelcontextprotocol/protocolVersion"];
  if (typeof requested !== "string") return error(-32602, "protocolVersion must be a string");
  if (requested !== PROTOCOL_VERSION) {
    return error(
      -32022,
      "Unsupported protocol version",
      { supported: [PROTOCOL_VERSION], requested },
    );
  }
  if (!isObj(meta["io.modelcontextprotocol/clientCapabilities"])) {
    return error(-32602, "clientCapabilities must be an object");
  }
  return null;
}

interface ToolSchema {
  readonly name: string;
  readonly requiredScope: string;
  readonly destructive: boolean;
  readonly description: string;
  readonly inputSchema: Obj;
}

function toolSchema(name: string, requiredScope: string, destructive: boolean, description: string, inputSchema: Obj): ToolSchema {
  return { name, requiredScope, destructive, description, inputSchema };
}

type Handler = (args: Obj) => Obj;

class MCPServer {
  tools: Map<string, ToolSchema> = new Map();
  handlers: Map<string, Handler> = new Map();

  constructor(
    public name: string,
    public title: string,
    public description: string,
    public version: string,
    public url: string,
    public trustedIssuer: string,
  ) {}

  get serverInfo(): Obj {
    return { name: this.name, version: this.version };
  }

  register(schema: ToolSchema, handler: Handler): void {
    if (this.tools.has(schema.name)) throw new Error(`duplicate tool: ${schema.name}`);
    this.tools.set(schema.name, schema);
    this.handlers.set(schema.name, handler);
  }

  result(fields: Obj): Obj {
    return {
      resultType: "complete",
      ...fields,
      _meta: { "io.modelcontextprotocol/serverInfo": this.serverInfo },
    };
  }

  discover(meta: Obj): Obj {
    const invalid = validateMeta(meta);
    if (invalid) return invalid;
    return this.result({
      supportedVersions: [PROTOCOL_VERSION],
      capabilities: { tools: { listChanged: false } },
      ttlMs: 3_600_000,
      cacheScope: "public",
    });
  }

  toolsList(meta: Obj): Obj {
    const invalid = validateMeta(meta);
    if (invalid) return invalid;
    const tools: Json[] = [...this.tools.values()]
      .sort((a, b) => (a.name < b.name ? -1 : a.name > b.name ? 1 : 0))
      .map((tool) => ({
        name: tool.name,
        description: tool.description,
        inputSchema: tool.inputSchema,
        annotations: {
          readOnlyHint: !tool.destructive,
          destructiveHint: tool.destructive,
        },
      }));
    return this.result({ tools, ttlMs: 60_000, cacheScope: "private" });
  }

  registryDocument(): Obj {
    return {
      $schema: REGISTRY_SCHEMA,
      name: this.name,
      title: this.title,
      description: this.description,
      version: this.version,
      remotes: [{ type: "streamable-http", url: this.url }],
    };
  }
}

class Token {
  constructor(
    readonly user: string,
    readonly issuer: string,
    readonly audience: string,
    readonly scopes: ReadonlySet<string>,
    readonly expiresAt: number,
  ) {}

  hasScope(scope: string): boolean {
    return this.scopes.has(scope);
  }

  isExpired(t: number): boolean {
    return t >= this.expiresAt;
  }
}

function argumentsDigest(args: Obj): string {
  const normalized = JSON.stringify(sortKeysDeep(args));
  return createHash("sha256").update(normalized, "utf8").digest("hex");
}

class ApprovalRecord {
  constructor(
    readonly actor: string,
    readonly tool: string,
    readonly argumentsDigest: string,
    readonly target: string,
    readonly expiresAt: number,
  ) {}

  static forAction(actor: string, tool: string, args: Obj, target: string, expiresAt: number): ApprovalRecord {
    return new ApprovalRecord(actor, tool, argumentsDigest(args), target, expiresAt);
  }

  authorize(actor: string, tool: string, args: Obj, target: string, t: number): [boolean, string] {
    if (this.actor !== actor) return [false, "approval actor does not match token subject"];
    if (this.tool !== tool) return [false, "approval tool does not match requested tool"];
    if (this.target !== target) return [false, "approval target does not match this server"];
    if (this.argumentsDigest !== argumentsDigest(args)) return [false, "approval arguments do not match requested action"];
    if (t >= this.expiresAt) return [false, "approval has expired"];
    return [true, "ok"];
  }
}

function policyDecide(
  server: MCPServer,
  tool: string,
  token: Token,
  args: Obj,
  t: number,
  approval: ApprovalRecord | null = null,
): [boolean, string] {
  if (token.issuer !== server.trustedIssuer) return [false, "token issuer is not trusted by this server"];
  if (token.audience !== server.url) return [false, "token audience does not match this server"];
  if (token.isExpired(t)) return [false, "token has expired"];
  const schema = server.tools.get(tool);
  if (schema === undefined) return [false, `no such tool: ${tool}`];
  if (!token.hasScope(schema.requiredScope)) return [false, `missing scope: ${schema.requiredScope}`];
  if (jsonDumps(args).length > 8192) return [false, "payload too large"];
  if (schema.destructive) {
    if (approval === null) return [false, "destructive tool requires an action-bound approval"];
    const [approved, reason] = approval.authorize(token.user, tool, args, server.url, t);
    if (!approved) return [false, reason];
  }
  return [true, "ok"];
}

function redact(payload: Obj): Obj {
  let text = jsonDumps(payload);
  text = text.replace(/[\w.+-]+@[\w-]+\.[\w.-]+/g, "[email]");
  text = text.replace(/\b\d{3}-\d{2}-\d{4}\b/g, "[ssn]");
  return JSON.parse(text) as Obj;
}

interface AuditEntry {
  readonly ts: number;
  readonly user: string;
  readonly issuer: string;
  readonly tool: string;
  readonly outcome: string;
  readonly args_redacted: Obj;
  readonly response_redacted: Obj;
}

function auditEntry(ts: number, user: string, issuer: string, tool: string, outcome: string, argsRedacted: Obj, responseRedacted: Obj): AuditEntry {
  return { ts, user, issuer, tool, outcome, args_redacted: argsRedacted, response_redacted: responseRedacted };
}

function dispatch(
  server: MCPServer,
  token: Token,
  tool: string,
  args: Obj,
  meta: Obj,
  audit: AuditEntry[],
  approval: ApprovalRecord | null = null,
): Obj {
  const invalid = validateMeta(meta);
  if (invalid) return invalid;
  const t = now();
  const [allowed, reason] = policyDecide(server, tool, token, args, t, approval);
  if (!allowed) {
    audit.push(auditEntry(t, token.user, token.issuer, tool, `denied:${reason}`, redact(args), {}));
    return error(-32000, reason);
  }
  let response: Obj;
  try {
    response = server.handlers.get(tool)!(args);
  } catch (exc) {
    audit.push(auditEntry(t, token.user, token.issuer, tool, "handler_error", redact(args), {}));
    return server.result({
      content: [{ type: "text", text: exc instanceof Error ? exc.message : String(exc) }],
      isError: true,
    });
  }
  audit.push(auditEntry(t, token.user, token.issuer, tool, "allowed", redact(args), redact(response)));
  return server.result({
    content: [{ type: "text", text: jsonDumps(response) }],
    structuredContent: response,
    isError: false,
  });
}

function validateRegistryDocument(document: unknown): string[] {
  if (!isObj(document)) return ["server.json must be an object"];
  const issues: string[] = [];
  const has = (k: string) => Object.prototype.hasOwnProperty.call(document, k);

  for (const key of ["name", "description", "version"]) {
    if (!has(key)) issues.push(`missing ${key}`);
  }

  const schemaUri = document["$schema"];
  if (has("$schema") && schemaUri !== REGISTRY_SCHEMA) issues.push("unsupported registry schema");

  const name = document.name;
  if (has("name") && (
    typeof name !== "string"
    || !(pyLen(name) >= 3 && pyLen(name) <= 200)
    || !SERVER_NAME_RE.test(name)
  )) {
    issues.push("name must match namespace/server and be 3-200 characters");
  }

  const description = document.description;
  if (has("description") && (
    typeof description !== "string" || !(pyLen(description) >= 1 && pyLen(description) <= 100)
  )) {
    issues.push("description must be a 1-100 character string");
  }

  const title = document.title;
  if (has("title") && (
    typeof title !== "string" || !(pyLen(title) >= 1 && pyLen(title) <= 100)
  )) {
    issues.push("title must be a 1-100 character string");
  }

  const version = document.version;
  if (has("version") && (
    typeof version !== "string"
    || !(pyLen(version) >= 1 && pyLen(version) <= 255)
    || VERSION_RANGE_RE.test(version)
    || version.toLowerCase() === "latest"
  )) {
    issues.push("version must be one concrete 1-255 character version");
  }

  const remotes = document.remotes;
  if (!Array.isArray(remotes) || remotes.length === 0) {
    issues.push("remote profile requires a non-empty remotes list");
  } else {
    remotes.forEach((remote, index) => {
      if (!isObj(remote)) {
        issues.push(`remotes[${index}] must be an object`);
        return;
      }
      if (remote.type !== "streamable-http" && remote.type !== "sse") {
        issues.push(`remotes[${index}].type must be streamable-http or sse`);
      }
      const remoteUrl = remote.url;
      if (typeof remoteUrl !== "string" || !REMOTE_URL_RE.test(remoteUrl)) {
        issues.push(`remotes[${index}].url must be an http(s) URL template`);
      }
    });
  }
  return issues;
}

function reverseDnsNamespace(domain: string): string {
  const normalized = domain.toLowerCase().replace(/\.+$/, "");
  const labels = normalized.split(".");
  if (labels.length < 2 || labels.some((label) => !DOMAIN_LABEL_RE.test(label))) {
    throw new Error("publisher domain must be a valid multi-label DNS name");
  }
  return [...labels].reverse().join(".");
}

function validatePublisherNamespace(document: unknown, verifiedDomain: string): string[] {
  if (!isObj(document) || typeof document.name !== "string") return [];
  const name = document.name;
  const slash = name.indexOf("/");
  const namespace = slash === -1 ? name : name.slice(0, slash);
  const expected = reverseDnsNamespace(verifiedDomain);
  if (namespace !== expected && !namespace.startsWith(`${expected}.`)) {
    return [`name namespace must be ${expected} or its child for verified domain ${verifiedDomain}`];
  }
  return [];
}

function validateRuntimeAlignment(document: Obj, discovery: unknown): string[] {
  if (!isObj(discovery)) return ["server/discover result must be an object"];
  const meta = discovery._meta;
  const serverInfo = isObj(meta) ? meta["io.modelcontextprotocol/serverInfo"] : null;
  if (!isObj(serverInfo)) return ["server/discover must include serverInfo for registry drift checks"];

  const issues: string[] = [];
  if (serverInfo.name !== document.name) issues.push("runtime serverInfo.name does not match server.json name");
  if (serverInfo.version !== document.version) issues.push("runtime serverInfo.version does not match server.json version");
  return issues;
}

class Registry {
  entries: Map<string, Obj> = new Map();
  runtimeDiscovery: Map<string, Obj> = new Map();

  constructor(public publisherDomain: string = PUBLISHER_DOMAIN) {}

  register(server: MCPServer): void {
    const document = server.registryDocument();
    const issues = validateRegistryDocument(document);
    issues.push(...validatePublisherNamespace(document, this.publisherDomain));
    if (issues.length > 0) throw new Error(issues.join("; "));
    const discovery = server.discover(requestMeta());
    if ("error" in discovery) throw new Error("runtime discovery failed");
    const alignmentIssues = validateRuntimeAlignment(document, discovery);
    if (alignmentIssues.length > 0) throw new Error(alignmentIssues.join("; "));
    this.entries.set(server.name, structuredClone(document));
    this.runtimeDiscovery.set(server.name, structuredClone(discovery));
  }

  search(query: string): string[] {
    const needle = query.toLowerCase();
    return [...this.entries.entries()]
      .filter(([name, entry]) =>
        name.toLowerCase().includes(needle)
        || String(entry.title).toLowerCase().includes(needle)
        || String(entry.description).toLowerCase().includes(needle))
      .map(([name]) => name)
      .sort();
  }
}

function buildReadonlyServer(): MCPServer {
  const server = new MCPServer(
    "com.example/internal-readonly",
    "Internal Read-Only Tools",
    "Read-only incident and data lookup tools.",
    "1.0.0",
    "https://mcp.internal.example.com/readonly",
    "https://auth.internal.example.com",
  );
  server.register(
    toolSchema(
      "postgres.readonly",
      "postgres:query:readonly",
      false,
      "Run an approved read-only query.",
      {
        type: "object",
        properties: { sql: { type: "string" } },
        required: ["sql"],
        additionalProperties: false,
      },
    ),
    (args) => ({ rows: [[1]], sql: args.sql }),
  );
  server.register(
    toolSchema(
      "s3.list",
      "s3:list",
      false,
      "List objects in one approved bucket.",
      {
        type: "object",
        properties: { bucket: { type: "string" } },
        required: ["bucket"],
        additionalProperties: false,
      },
    ),
    (args) => ({ bucket: args.bucket, objects: ["a/b.txt"] }),
  );
  return server;
}

function buildDestructiveServer(): MCPServer {
  const server = new MCPServer(
    "com.example/internal-destructive",
    "Internal Destructive Tools",
    "State-changing tools behind explicit approval.",
    "1.0.0",
    "https://mcp.internal.example.com/destructive",
    "https://auth.internal.example.com",
  );
  server.register(
    toolSchema(
      "jira.create",
      "jira:write",
      true,
      "Create one Jira issue after explicit approval.",
      {
        type: "object",
        properties: { title: { type: "string" } },
        required: ["title"],
        additionalProperties: false,
      },
    ),
    (args) => ({ id: "PROJ-99", title: args.title, created: true }),
  );
  return server;
}

function main(): void {
  const readonly = buildReadonlyServer();
  const destructive = buildDestructiveServer();
  const registry = new Registry();
  registry.register(readonly);
  registry.register(destructive);
  const audit: AuditEntry[] = [];

  const readonlyToken = new Token(
    "u42",
    readonly.trustedIssuer,
    readonly.url,
    new Set(["postgres:query:readonly", "s3:list"]),
    now() + 3_600,
  );
  const approvedToken = new Token(
    "u42",
    destructive.trustedIssuer,
    destructive.url,
    new Set(["jira:write"]),
    now() + 3_600,
  );
  const approvedArgs: Obj = { title: "new bug" };
  const approval = ApprovalRecord.forAction(
    approvedToken.user,
    "jira.create",
    approvedArgs,
    destructive.url,
    now() + 900,
  );

  console.log("=== registry metadata and runtime discovery ===");
  console.log(JSON.stringify(registry.entries.get(readonly.name), null, 2));
  console.log(JSON.stringify(registry.runtimeDiscovery.get(readonly.name), null, 2));
  console.log("tools:", JSON.stringify(readonly.toolsList(requestMeta()), null, 2));

  console.log("\n=== policy-gated calls ===");
  console.log(pyRepr(dispatch(
    readonly,
    readonlyToken,
    "postgres.readonly",
    { sql: "SELECT 1" },
    requestMeta(),
    audit,
  )));
  console.log(pyRepr(dispatch(
    destructive,
    approvedToken,
    "jira.create",
    approvedArgs,
    requestMeta(),
    audit,
    approval,
  )));

  console.log("\n=== audit log ===");
  for (const entry of audit) {
    console.log(jsonDumps({ ...entry }, true));
  }
}

main();

